Image *ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  MngInfo *mng_info = NULL;
  size_t file_size;
  FILE *file_handle;

  // Open the image file for reading
  file_handle = fopen(image_info->filename, "rb");
  if (!file_handle)
  {
    ThrowFileException(exception, FileOpenError, "UnableToOpenFile", image_info->filename);
    return NULL;
  }

  // Check the JNG signature
  unsigned char signature[8];
  if (fread(signature, sizeof(unsigned char), 8, file_handle) != 8)
  {
    fclose(file_handle);
    ThrowFileException(exception, CorruptImageError, "UnableToReadImageData", image_info->filename);
    return NULL;
  }

  if (memcmp(signature, "\213PNG\r\n", 8))
  {
    fclose(file_handle);
    ThrowFileException(exception, CorruptImageError, "NotAJNGImage", image_info->filename);
    return NULL;
  }

  // Determine the file size
  fseek(file_handle, 0, SEEK_END);
  file_size = ftell(file_handle);
  rewind(file_handle);

  // Allocate MngInfo structure
  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(MngInfo));
  if (!mng_info)
  {
    fclose(file_handle);
    ThrowMemoryException(exception);
    return NULL;
  }

  memset(mng_info, 0, sizeof(MngInfo));

  // Read the image data and populate the Image structure
  image = AcquireImage(image_info, exception);
  if (!image)
  {
    fclose(file_handle);
    RelinquishMagickMemory(mng_info);
    return NULL;
  }

  // Read image dimensions and validate
  if (ReadJNGImageDimensions(file_handle, mng_info, image, exception) != MagickPass)
  {
    fclose(file_handle);
    DestroyImage(image);
    RelinquishMagickMemory(mng_info);
    return NULL;
  }

  // Continue reading image data based on the MngInfo structure
  if (ReadJNGImageData(file_handle, mng_info, image, exception) != MagickPass)
  {
    fclose(file_handle);
    DestroyImage(image);
    RelinquishMagickMemory(mng_info);
    return NULL;
  }

  // Clean up
  fclose(file_handle);
  RelinquishMagickMemory(mng_info);

  return image;
}

