  image->file = fopen(image_info->filename, "rb");
  if (!image->file)
    {
      ThrowFileException(exception, FileOpenError, image_info->filename, "JNG");
      image = DestroyImageList(image);
      mng_info = (MngInfo *) RelinquishMagickMemory(mng_info);
      return (Image *) NULL;
    }

  /* Verify the JNG signature */
  {
    size_t
      bytes_read;

    unsigned char
      signature[8];

    bytes_read = fread(signature, sizeof(unsigned char), 8, image->file);
    if (bytes_read != 8 || memcmp(signature, "\211PNG", 4) != 0)
      {
        fclose(image->file);
        image->file = (FILE *) NULL;
        ThrowMagickException(exception, GetMagickModule(),
                             CorruptImageError, "InvalidJNGSignature",
                             "`%s'", image_info->filename);
        image = DestroyImageList(image);
        mng_info = (MngInfo *) RelinquishMagickMemory(mng_info);
        return (Image *) NULL;
      }
  }

  /* Continue reading the image and processing based on JNG format rules */
  /* ... */

  /* Handle invalid image dimensions */
  if (image->columns == 0 || image->rows == 0)
    {
      fclose(image->file);
      image->file = (FILE *) NULL;
      ThrowMagickException(exception, GetMagickModule(), ImageError,
                           "InvalidImageDimensions", "`%s'",
                           image_info->filename);
      image = DestroyImageList(image);
      mng_info = (MngInfo *) RelinquishMagickMemory(mng_info);
      return (Image *) NULL;
    }

  /* Finalize and return the Image structure */
  image->blob = (void *) mng_info;
  return image;
