Image *
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  MngInfo *mng_info;
  int status;
  size_t length;
  ssize_t count;
  unsigned char buffer[16];
  FILE *file;

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL)
    return (Image *) NULL;

  file = fopen(image_info->filename, "rb");
  if (file == (FILE *) NULL)
  {
    ThrowFileException(exception, FileOpenError, UnableToOpenFile,
      image_info->filename);
    image = DestroyImageList(image);
    return (Image *) NULL;
  }

  count = fread(buffer, 1, 8, file);
  if ((count != 8) || (memcmp(buffer, "\212PNG\r\n\n", 8) != 0))
  {
    ThrowException(exception, CorruptImageError, InvalidImageFile,
      image_info->filename);
    image = DestroyImageList(image);
    fclose(file);
    return (Image *) NULL;
  }

  if (image->columns == 0 || image->rows == 0)
  {
    ThrowException(exception, OptionError, InvalidImageSize,
      image_info->filename);
    image = DestroyImageList(image);
    fclose(file);
    return (Image *) NULL;
  }

  mng_info = (MngInfo *) AcquireMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
  {
    ThrowException(exception, ResourceLimitError, MemoryAllocationFailed,
      image_info->filename);
    image = DestroyImageList(image);
    fclose(file);
    return (Image *) NULL;
  }

  (void) memset(mng_info, 0, sizeof(*mng_info));
  mng_info->signature = 0x4d4e4700;

  while (!feof(file))
  {
    count = fread(buffer, 1, 8, file);
    if (count != 8)
      break;

    length = (((size_t) buffer[0] << 24) |
              ((size_t) buffer[1] << 16) |
              ((size_t) buffer[2] << 8) |
              ((size_t) buffer[3]));
    switch ((int) buffer[4])
    {
      case 0x00:
      {
        if (length > 0)
          (void) fread(buffer, 1, length, file);
        break;
      }
      default:
      {
        (void) fseek(file, (long) length, SEEK_CUR);
        break;
      }
    }
  }

  if (!feof(file))
    (void) fseek(file, 0, SEEK_SET);

  status = ReadBlob(image, 1, buffer, exception);
  if (status != 1)
  {
    image = DestroyImageList(image);
    fclose(file);
    return (Image *) NULL;
  }

  fclose(file);

  image->type = TrueColorType;
  return image;
}

