{
  Image *image;
  MngInfo *mng_info;
  FILE *file;

  file = fopen(image_info->filename, "rb");
  if (!file)
  {
    ThrowFileException(exception, FileOpenError, UnableToOpenImage, image_info->filename);
    return (Image *) NULL;
  }

  {
    unsigned char signature[8];
    if (fread(signature, 1, 8, file) != 8 || memcmp(signature, "\213MNG\r\n\032\n", 8))
    {
      fclose(file);
      ThrowReaderException(CorruptImageError, InvalidImageFormat, image_info->filename);
      return (Image *) NULL;
    }
  }

  {
    size_t size = 0;
    fseek(file, 0, SEEK_END);
    size = (size_t) ftell(file);
    fseek(file, 0, SEEK_SET);
    if (size < 17)
    {
      fclose(file);
      ThrowReaderException(CorruptImageError, InvalidImageFormat, image_info->filename);
      return (Image *) NULL;
    }
  }

  mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
  if (mng_info == (MngInfo *) NULL)
  {
    fclose(file);
    ThrowReaderException(ResourceLimitError, UnableToAllocateMemory, image_info->filename);
    return (Image *) NULL;
  }

  image = (Image *) NULL;
  image = ReadImageFile(image_info, file, mng_info, exception);
  if (image == (Image *) NULL)
  {
    fclose(file);
    RelinquishMemory(mng_info);
    return (Image *) NULL;
  }

  if (image->columns <= 0 || image->rows <= 0)
  {
    RelinquishMemory(mng_info);
    fclose(file);
    ThrowReaderException(CorruptImageError, InvalidImageGeometry, image_info->filename);
    return (Image *) NULL;
  }

  image->mng_info = mng_info;
  fclose(file);
  return image;
}

Image *
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  MngInfo *mng_info = NULL;
  FILE *file = NULL;
  size_t size;

  file = fopen(image_info->filename, "rb");
  if (file == NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "UnableToOpenFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (VerifyJNGSignature(file) == MagickFalse)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "NotJNGFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  size = GetFileSize(file);
  if (size == 0)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "EmptyFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  mng_info = AcquireMngInfo(image_info->filename);
  if (mng_info == (MngInfo *) NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "MemoryAllocationFailed", "%s", image_info->filename);
    return (Image *) NULL;
  }

  image = ReadJNGImageBody(file, mng_info, image_info, exception);
  if (image == (Image *) NULL)
  {
    (void) fclose(file);
    mng_info = RelinquishMngInfo(mng_info);
    return (Image *) NULL;
  }

  (void) fclose(file);

  if ((image->columns == 0) || (image->rows == 0))
  {
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "InvalidImageDimensions", "%s", image_info->filename);
    image = DestroyImageList(image);
    mng_info = RelinquishMngInfo(mng_info);
    return (Image *) NULL;
  }

  return image;
}
